{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss combines advantage signals with the cost gap to encourage preferences that favor smaller costs while amplifying the advantage disparities. By leveraging advantage and cost gap signals, it promotes preference-based learning aligned with lower costs. The pairing mode ensures comparisons are made between pairs, capturing relative superiority.",
  "pseudocode": "loss = -logsigmoid(ops.mul((advantage_w - advantage_l), ops.exp(ops.mul(cost_gap, alpha))))",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage_cost",
    "link_family": "pairwise",
    "agg_family": "none",
    "constraint_family": "cost_advantage"
  },
  "operators_used": ["logsigmoid", "mul", "exp"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    cost_gap = batch[\"cost_gap\"]\n    # Compute pairwise preference signal\n    preference_signal = ops.mul(ops.sub(advantage_w, advantage_l), ops.exp(ops.mul(cost_gap, alpha)))\n    loss = -ops.logsigmoid(preference_signal)\n    # Return mean over batch\n    return ops.mean(loss)"
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss combines advantage signals with cost gap to prioritize pairs where the advantage difference aligns with the cost gap, encouraging the model to prefer options with better advantage-cost trade-offs. Using log sigmoid for advantage helps emphasize meaningful differences while maintaining stability. The pairwise approach directly compares pairs, optimizing preference ordering effectively.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l + alpha * cost_gap) * weight)",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage_cost",
    "link_family": "logsigmoid",
    "agg_family": "pairwise",
    "constraint_family": "margin",
    "other_hparams": "alpha default 1.0"
  },
  "operators_used": ["logsigmoid", "mul", "add", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    advantage_w = batch.get(\"advantage_w\", None)\n    advantage_l = batch.get(\"advantage_l\", None)\n    cost_gap = batch[\"cost_gap\"]\n    # Compute pairwise advantage difference\n    advantage_diff = ops.sub(advantage_w, advantage_l)\n    # Incorporate cost gap scaled by alpha\n    margin = ops.add(advantage_diff, ops.mul(alpha, cost_gap))\n    # Apply logsigmoid to compute preference probability\n    preference = ops.logsigmoid(margin)\n    # Loss is negative log likelihood weighted by pair weight\n    loss_value = ops.neg(ops.mean(ops.mul(preference, weight)))\n    return loss_value"
}

{
  "name": "pairwise_advantage_cost_gap",
  "intuition": "This loss uses the advantage and cost_gap signals to encourage selecting higher advantage and lower cost_gap, promoting preferred choices. The pairwise comparison amplifies the preference by computing difference-based signals, making the model more sensitive to relative quality differences between options.",
  "pseudocode": "loss = mean( logsigmoid( advantage_w - advantage_l + alpha * (cost_gap) ) * weight )",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    cost_gap = batch.get(\"cost_gap\", ops.zeros_like(advantage_w))\n    diff_adv = ops.sub(advantage_w, advantage_l)\n    scaled_cost = ops.mul(ops.constant(alpha), cost_gap)\n    signal = ops.add(diff_adv, scaled_cost)\n    loss_terms = ops.mul(ops.logsigmoid(signal), weight)\n    loss = ops.mean(loss_terms)\n    return loss"
}

{
  "name": "loss_exp_advantage_sigmoid_gap",
  "intuition": "Fine-tuning the hyperparameters enhances the focus on pairs with significant advantage imbalance. Increasing the clamp range to ±10 allows capturing larger advantage differences, while adjusting the importance weight decay via the exponential scaling ensures the model emphasizes more critical pairs without overemphasizing outliers. The sigmoid remains as the link function for smooth preference enforcement, and weighted sum aggregation maintains emphasis on high-importance pairs. These modifications improve the loss's sensitivity to meaningful advantage disparities, thereby better guiding the model training.",
  "pseudocode": "adv_diff = advantage_w - advantage_l\nweighting = exp(clamp(adv_diff, -10, 10))\nscore_diff = log_prob_w - log_prob_l\nsigmoid_term = sigmoid(score_diff)\npair_loss = -log(sigmoid_term)\nweighted_loss = pair_loss * weighting * weight\nloss = sum(weighted_loss) / sum(weighting * weight)",
  "hyperparams": {
    "paradigm_family": "weighted_pairwise_importance",
    "signal_family": "advantage_gap",
    "link_family": "sigmoid",
    "agg_family": "weighted_sum",
    "constraint_family": "clamp_stabilized"
  },
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_w",
      "advantage_l"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    adv_diff = ops.clamp(ops.sub(adv_w, adv_l), -10.0, 10.0)\n    weighting = ops.exp(adv_diff)\n    score_diff = ops.sub(lpw, lpl)\n    sig_term = ops.sigmoid(score_diff)\n    # To avoid log(0), clamp sigmoid output minimum\n    sig_term_clamped = ops.clamp(sig_term, 1e-7, 1.0)\n    pair_loss = ops.neg(ops.log(sig_term_clamped))\n    weighted_loss = ops.mul(pair_loss, ops.mul(weighting, weight))\n    total_weight = ops.sum(ops.mul(weighting, weight)) + 1e-7\n    loss = ops.div(ops.sum(weighted_loss), total_weight)\n    return loss"
  }
}

{
  "name": "combined_loss_crossover_stabilized",
  "intuition": "Simplified the original loss to stabilize training by removing redundant or unstable terms and ensuring numerical stability. Replaced the importance weighting exponential with a clamp on advantage gap to control scale, eliminated the sigmoid weighting since it can cause instability, and used a single stable ranking loss term based on tanh transformed advantage gap. Clamped advantage differences to [-5,5] to avoid extreme values and ensured weights default to ones when missing, preserving simplicity and stable gradient flow.",
  "generated_loss": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(batch['log_prob_w']))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    adv_gap_raw = ops.sub(adv_w, adv_l)\n    adv_gap = ops.clamp(adv_gap_raw, -5.0, 5.0)\n    rank_gap_score = ops.tanh(ops.mul(scale, adv_gap))\n    # Stable rank loss encourages rank_gap_score towards 1\n    loss_per_pair = ops.mul(ops.sub(ops.ones_like(rank_gap_score), rank_gap_score), weight)\n    return ops.mean(loss_per_pair)",
  "implementation_hint": {
    "mode": "pairwise",
    "returns": "scalar",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_w",
      "advantage_l"
    ]
  }
}

