  "name": "contrastive_softmax_delta_regret_stabilized",
  "intuition": "Simplified and stabilized the original softmax margin loss by directly using a numerically stable sigmoid-based probability instead of separate exp computations for margin and -margin, preventing potential overflow. Clamped margin to avoid extreme values and clamped final probability to avoid log(0). This reduces complexity, avoids syntax issues, and improves numerical stability while preserving the contrastive softmax semantics with delta_regret adjustment.",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "delta_regret"
    ],
    "returns": "scalar"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    delta_regret = batch['delta_regret']\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 0.5)))\n    margin_raw = ops.add(ops.sub(lpw, lpl), ops.mul(beta, delta_regret))\n    margin = ops.clamp(margin_raw, -10.0, 10.0)\n    softmax_prob = ops.sigmoid(margin)\n    softmax_prob_clamped = ops.clamp(softmax_prob, 1e-7, 1.0)\n    pair_loss = ops.neg(ops.log(softmax_prob_clamped))\n    weighted_loss = ops.mul(pair_loss, weight)\n    total_weight = ops.sum(weight) + 1e-7\n    loss = ops.div(ops.sum(weighted_loss), total_weight)\n    return loss"
}

